public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }
    int operations = 0;
    while (true) {
        boolean allEqual = true;
        for (int i = 1; i < n; i++) {
            if (arr[i] != arr[i - 1]) {
                allEqual = false;
                break;
            }
        }
        if (allEqual) {
            break;
        }
        int maxIndex = 0;
        for (int i = 1; i < n; i++) {
            if (arr[i] > arr[maxIndex]) {
                maxIndex = i;
            }
        }
        int minIndex = 0;
        for (int i = 1; i < n; i++) {
            if (arr[i] < arr[minIndex]) {
                minIndex = i;
            }
        }
        arr[maxIndex]--;
        arr[minIndex]++;
        operations++;
    }
    return operations;
}

