public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[][] dirs = new int[][]{{0, 1}, {1, 0}, {1, 1}, {1, -1}};
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            for (int[] dir : dirs) {
                int len = 0;
                int x = i, y = j;
                while (x >= 0 && x < m && y >= 0 && y < n && mat[x][y] == 1) {
                    len++;
                    x += dir[0];
                    y += dir[1];
                }
                maxLen = Math.max(maxLen, len);
            }
        }
    }
    return maxLen;
}

