public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        throw new IllegalArgumentException("Invalid input: points array must have exactly 3 elements");
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    // Check if the points are collinear
    if (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2) == 0) {
        return false;
    }

    // Check if the points form a triangle
    if (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2) < 0) {
        return false;
    }

    // Check if the points form a boomerang
    if (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2) == 0) {
        return true;
    }

    return false;
}

