            currentLength++;
        } else {
            energy = Math.max(energy, currentLength);
            currentChar = s.charAt(i);
            currentLength = 1;
        }
    }
    energy = Math.max(energy, currentLength);
    return energy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    Collections.sort(result);
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueNums = new HashSet<>();
    for (int num : nums) {
        uniqueNums.add(num);
    }
    int sum = 0;
    for (int num : uniqueNums) {
        sum += num;
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    int currentSquare = 1;
    while (currentSquare <= n) {
        count++;
        currentSquare = currentSquare * currentSquare;
    }
    return count;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (String word : words) {
        result.append(new StringBuilder(word).reverse().toString());
        result.append(" ");
    }
    return result.toString().trim();
}
